# Sign-up and login done right: a unique salt and a slow hash per user.
import hashlib
import hmac

users = {}

def hash_password(password, salt):
    return hashlib.pbkdf2_hmac("sha256", password.encode(), salt, 100_000).hex()

def register(name, password, salt):
    users[name] = {"salt": salt, "hash": hash_password(password, salt)}

def login(name, password):
    user = users.get(name)
    if not user:
        return False
    attempt = hash_password(password, user["salt"])
    return hmac.compare_digest(attempt, user["hash"])   # constant-time comparison

# In a real app each salt comes from os.urandom(16); fixed here so the output is repeatable.
register("ana", "correct horse battery staple", bytes.fromhex("8f1a2b3c4d5e6f708192a3b4c5d6e7f8"))
register("ben", "correct horse battery staple", bytes.fromhex("0102030405060708090a0b0c0d0e0f10"))

for name, record in users.items():
    print(f"{name}: salt {record['salt'].hex()[:8]}... hash {record['hash'][:16]}...")
print("same password, different hashes:", users["ana"]["hash"] != users["ben"]["hash"])
print("ana, right password:", login("ana", "correct horse battery staple"))
print("ana, wrong password:", login("ana", "password123"))
print("unknown user:", login("eve", "anything"))

import hashlib
import time

passwords = {"ana": "123456", "ben": "dragon", "chen": "123456"}
common = ["password", "123456", "qwerty", "dragon", "letmein"]

plain = {u: hashlib.sha256(p.encode()).hexdigest() for u, p in passwords.items()}
print("unsalted: ana and chen share a hash:", plain["ana"] == plain["chen"])
table = {hashlib.sha256(w.encode()).hexdigest(): w for w in common}
print("lookup table cracks:", {u: table.get(h, "?") for u, h in plain.items()})

salts = {"ana": b"\x11" * 16, "ben": b"\x22" * 16, "chen": b"\x33" * 16}
salted = {u: hashlib.pbkdf2_hmac("sha256", p.encode(), salts[u], 100_000).hex() for u, p in passwords.items()}
print("\nsalted: ana and chen share a hash:", salted["ana"] == salted["chen"])
print("lookup table cracks:", {u: table.get(h, "?") for u, h in salted.items()})

start = time.perf_counter()
for _ in range(20):
    hashlib.sha256(b"guess").digest()
fast = (time.perf_counter() - start) / 20
start = time.perf_counter()
hashlib.pbkdf2_hmac("sha256", b"guess", b"salt", 100_000)
slow = time.perf_counter() - start
print("\neach PBKDF2 guess is over 1,000x slower than plain SHA-256:", slow / fast > 1_000)

