import string

COMMON = {"password", "123456", "qwerty", "p@ssw0rd!", "summer2026", "iloveyou"}


def pool_size(pw):
    size = 0
    if any(c in string.ascii_lowercase for c in pw): size += 26
    if any(c in string.ascii_uppercase for c in pw): size += 26
    if any(c in string.digits for c in pw): size += 10
    if any(c in string.punctuation or c == " " for c in pw): size += 33
    return size


def crack_time(guesses, per_second=1e9):
    seconds = guesses / per_second
    for unit, length in [("years", 31_557_600), ("days", 86_400), ("hours", 3_600), ("minutes", 60)]:
        if seconds >= length:
            value = seconds / length
            return f"{value:.1e} {unit}" if value >= 1e6 else f"{value:,.0f} {unit}"
    return "under a minute"


for pw in ["dragon", "P@ssw0rd!", "Tr0ub4dor&3", "correct horse battery staple"]:
    guesses = pool_size(pw) ** len(pw)
    note = "  <- on a common-password list: cracked instantly" if pw.lower() in COMMON else ""
    print(f"{pw:30} length {len(pw):2}, pool {pool_size(pw):2}: worst case {crack_time(guesses)}{note}")

